const HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Calgary Power Platform User Group (CPPUG)</title>\n<meta name=\"description\" content=\"The Calgary Power Platform User Group (CPPUG) helps Calgary makers learn, connect, and build with Microsoft Power Platform.\">\n<meta property=\"og:title\" content=\"Calgary Power Platform User Group (CPPUG)\">\n<meta property=\"og:description\" content=\"Learn, connect, and build with Microsoft Power Platform in Calgary.\">\n<meta property=\"og:image\" content=\"https://hackathon.cppug.ca/assets/images/logos/cppug-logo-white.png\">\n<link rel=\"icon\" href=\"https://hackathon.cppug.ca/favicon.svg\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Open+Sans:wght@400;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n@font-face { font-family: 'Norwester'; src: url('https://hackathon.cppug.ca/assets/fonts/norwester.otf') format('opentype'); font-display: swap; }\n:root { --pink: #91338C; --blue: #5086F2; --purple: #4940AF; --yellow: #EBCC45; --green: #7DCF81; --lightblue: #8ED0F8; }\n* { box-sizing: border-box; }\nbody { margin: 0; font-family: 'Open Sans', Calibri, 'Segoe UI', sans-serif; color: #000; background: #fff; line-height: 1.6; }\na { color: inherit; }\nh1, h2 { font-family: 'Norwester', 'Trebuchet MS', sans-serif; font-weight: 400; letter-spacing: .01em; margin: 0 0 .5rem; }\n.hero { background: #000; color: #fff; text-align: center; padding: 3.5rem 1rem 4rem; }\n.hero img { width: min(320px, 70vw); height: auto; margin: 0 auto 1.5rem; display: block; }\n.hero .logo-anim { width: min(560px, 92vw); aspect-ratio: 16 / 9; border: 0; margin: 0 auto 1.5rem; display: block; background: #000; }\n.hero h1 { font-size: clamp(2rem, 6vw, 3.4rem); }\n.hero p { color: var(--lightblue); font-size: 1.2rem; margin: 0 auto 2rem; max-width: 40rem; }\n.btn { display: inline-block; margin: .4rem; padding: 1rem 2rem; border-radius: 50px; font-weight: 700; text-transform: uppercase; letter-spacing: .5px; text-decoration: none; border: 2px solid var(--yellow); }\n.btn.primary { background: var(--yellow); color: #000; }\n.btn.secondary { color: #fff; border-color: #fff; }\n.btn:hover { transform: translateY(-2px); }\n.event { background: #f5f5f5; padding: 3rem 1rem; text-align: center; }\n.event h2 { font-size: 2rem; }\n.event p { max-width: 40rem; margin: 0 auto 1.5rem; }\n.section { max-width: 1100px; margin: 0 auto; padding: 3.5rem 1rem; }\n.section h2 { font-size: 2.2rem; text-align: center; margin-bottom: 1.5rem; }\n.grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(230px, 1fr)); gap: 1.25rem; }\n.card { border-radius: 12px; padding: 1.5rem; color: #fff; }\n.card h3 { margin: 0 0 .5rem; font-size: 1.2rem; }\n.card p { margin: 0; }\n.c0 { background: var(--pink); } .c1 { background: var(--blue); } .c2 { background: var(--purple); } .c3 { background: var(--yellow); color: #000; }\n.vision { text-align: center; font-size: 1.3rem; font-style: italic; color: var(--purple); max-width: 44rem; margin: 0 auto 2rem; }\nfooter { background: #000; color: #fff; text-align: center; padding: 2rem 1rem; font-size: .95rem; }\nfooter a { color: var(--lightblue); }\n</style>\n</head>\n<body>\n<header class=\"hero\">\n  <iframe class=\"logo-anim\" src=\"/cppug-intro.svg\" title=\"Calgary Power Platform User Group logo animation. It plays once and stops on the logo.\" loading=\"eager\"></iframe>\n  <h1>Calgary Power Platform User Group</h1>\n  <p>Learn, connect, and build with Microsoft Power Platform. Everyone is welcome, from first app to expert.</p>\n  <a class=\"btn primary\" href=\"https://hackathon.cppug.ca/\">CPPUG Hackathon</a>\n  <a class=\"btn secondary\" href=\"https://www.meetup.com/calgary-power-platform-user-group/\" rel=\"noopener\">Join us on Meetup</a>\n</header>\n\n<section class=\"event\">\n  <h2>Power Platform Hackathon</h2>\n  <p>Saturday, October 10, 2026, 9:00 AM to 4:00 PM, at Microsoft Calgary. Teams build real solutions in one day, with mentors, demos, judging, and PPCC26 passes for the winners.</p>\n  <a class=\"btn primary\" href=\"https://hackathon.cppug.ca/\">Hackathon details and Participant Pack</a>\n</section>\n\n<section class=\"section\">\n  <h2>Why CPPUG exists</h2>\n  <p class=\"vision\">Aid Calgary's digital transformation using the Power Platform.</p>\n  <div class=\"grid\">\n    <div class=\"card c0\"><h3>Community</h3><p>A space to connect, network, and collaborate with Power Platform makers in Calgary and area.</p></div>\n    <div class=\"card c1\"><h3>Skills development</h3><p>Hands-on workshops and group learning, in person or virtual.</p></div>\n    <div class=\"card c2\"><h3>Mentorship</h3><p>Guidance for people who are new to the Power Platform ecosystem.</p></div>\n    <div class=\"card c3\"><h3>Non-profit and hackathons</h3><p>Building solutions for organizations that can use Microsoft 365 and the Power Platform better.</p></div>\n  </div>\n</section>\n\n<footer>\n  <p>Questions or want to help? Email <a href=\"mailto:communityleader@cppug.onmicrosoft.com\">communityleader@cppug.onmicrosoft.com</a> or message us on <a href=\"https://www.meetup.com/calgary-power-platform-user-group/\" rel=\"noopener\">Meetup</a>.</p>\n  <p>Calgary Power Platform User Group (CPPUG)</p>\n</footer>\n</body>\n</html>\n";
