export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.hostname === 'www.cppug.ca') { url.hostname = 'cppug.ca'; return Response.redirect(url.toString(), 301); }
    if (url.pathname === '/hackathon' || url.pathname.startsWith('/hackathon/')) { return Response.redirect('https://hackathon.cppug.ca/', 302); }
    if (url.pathname === '/cppug-intro.svg') { return new Response(SVG, { headers: { 'content-type': 'image/svg+xml', 'cache-control': 'public, max-age=86400' } }); }
    return new Response(HTML, { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'public, max-age=300' } });
  }
};
